insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('NA', 'default', 'Namibia reference chart of accounts', '{}'::jsonb, true, 'companies', array['NA-ICAN-IS', 'NA-ICAN-SFP']::text[], null, 'There is no legal chart of accounts in Namibia. The Companies Act, 2004 requires accounting records and annual financial statements, and the Institute of Chartered Accountants of Namibia (ICAN) has adopted IFRS Accounting Standards and the IFRS for SMEs Accounting Standard for them. This chart is original: four digits, blocked so that each range reaches one line of the IFRS-based statements, with the accounts a Namibian company keeps — a Namibia dollar current account and a foreign currency account side by side, VAT output and input tax, the net VAT settlement account, import VAT owed to the Namibia Revenue Agency (NamRA) on an import declaration, PAYE and social security payable, withholding tax and the irrecoverable VAT of s. 19(2) of the Value-Added Tax Act.', 'ifac-namibia')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

