insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('NA', 'NA-P-15', 'Purchase, standard rate 15 %, deductible', '{}'::jsonb, 'A local purchase at the general rate, made to carry on a taxable activity, on a tax invoice', 'percent', 15, 'purchase', 'domestic', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 18 and s. 19 — input tax is deducted from output tax for the period, on a tax invoice, tax debit note or tax credit note held when the return is furnished (s. 18(2)(a)); no deduction is made for what s. 19(2) lists. Declared on row 13 of the VAT 2 return, "Local Purchases", in the 15 % column; a credit note received goes to row 17, input adjustments. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NA', 'NA-P-15-CAP', 'Purchase of a capital good, 15 %, deductible', '{}'::jsonb, 'A local purchase of a capital good used to carry on a taxable activity', 'percent', 15, 'purchase', 'domestic', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 18 and s. 19, and the VAT 2 return, row 14 "Capital goods purchased locally", in the 15 % column; a credit note received goes to row 17. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', null, null, 115, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat2-return', null, null, null, null),
  ('NA', 'NA-P-15-ND', 'Purchase, standard rate 15 %, input tax not deductible', '{}'::jsonb, 'A passenger vehicle, entertainment, club subscriptions and the other purchases whose input tax s. 19(2) refuses', 'percent', 15, 'purchase', 'domestic', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 19(2) — no input tax is deducted on a taxable supply to, or import by, the registered person of (a) a passenger vehicle, unless the person deals in or hires out passenger vehicles, is a tour operator and the like; (b) goods or services acquired for entertainment, unless the person provides entertainment as a business; (c) petroleum products not wholly for use in the business; (d) fees or subscriptions to a sporting, social or recreational club. The tax follows the expense to account 6530 and reaches no row of the return. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NA', 'NA-P-EX', 'Purchase, exempt (local)', '{}'::jsonb, 'Bank charges, insurance, residential rent and the other exempt supplies bought locally', 'percent', 0, 'purchase', 'exempt', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 10 and Schedule IV — the supply is exempt, so there is no input tax. Declared on row 13 of the VAT 2 return in the exempt column; a credit note received goes to row 17 in the same column. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', null, null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat2-return', null, null, null, null),
  ('NA', 'NA-P-IMP', 'Import of goods, VAT paid on the import', '{}'::jsonb, 'VAT on goods entered for home consumption, paid by the importer on an import declaration and claimed as input tax', 'percent', 15, 'purchase', 'import', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 6(1)(b) and (2)(b) — tax is levied on the import of goods and paid by the importer, at 15 per cent of the value of the import fixed by s. 12(2); s. 14(1) — the importer furnishes an import declaration and pays on entry for home consumption, or by the 20th day of the month after the import where the goods are imported on a VAT import account; s. 18(2)(b) — the deduction needs the bill of entry. Declared on row 15 of the VAT 2 return, "Imported purchases". The tax is owed to NamRA and not to the supplier, so it waits on account 2125 until the import declaration is paid. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NA', 'NA-P-IMP-CAP', 'Import of a capital good, VAT paid on the import', '{}'::jsonb, 'VAT on a capital good imported to carry on a taxable activity', 'percent', 15, 'purchase', 'import', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 6(1)(b), s. 12 and s. 14 as for NA-P-IMP; row 16 of the VAT 2 return, "Imported capital goods". The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', null, null, 155, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat2-return', null, null, null, null),
  ('NA', 'NA-P-RC-SVC', 'Imported service, tax paid by the recipient and claimed back', '{}'::jsonb, 'A service supplied by a non-resident: the recipient declares and pays the tax, then deducts it as input tax', 'percent', 15, 'purchase', 'foreign_services_received', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 6(1)(b) and (2)(c) — tax is levied on an import of services and paid by the recipient; s. 14(2) as amended by the Value-Added Tax Amendment Act, 2024, s. 2 — the recipient furnishes an import declaration and pays within 20 days following the month in which the import was made (the amendment commences on a date the Minister fixes); s. 18 — the tax paid on an import is input tax. The VAT 2 form does not say where an import of services goes: the pack declares it on row 15, "Imported purchases", and the accountant must confirm that placement. The tax waits on account 2125 until the import declaration is paid. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', null, null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NA', 'NA-P-Z', 'Purchase, zero-rated (local)', '{}'::jsonb, 'A local purchase charged at zero per cent by the supplier', 'percent', 0, 'purchase', 'domestic', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 9 — a supply charged at zero per cent carries no tax to deduct. Declared on row 13 of the VAT 2 return in the zero-rated column; a credit note received goes to row 17 in the same column. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', null, null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat2-return', null, null, null, null),
  ('NA', 'NA-S-15', 'Sale, standard rate 15 %', '{}'::jsonb, 'The general rate on a taxable supply of goods or services by a registered person', 'percent', 15, 'sale', 'domestic', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 6(1) — tax is levied at the rate of 15 per cent on the value of every taxable supply by a registered person and of every import of goods or services other than an exempt import; s. 6(2) — the supplier accounts for it on a supply, the importer pays it on goods, the recipient pays it on imported services. Declared on row 8 of the VAT 2 return, "Trading: Sales/fees", in the 15 % column; a credit note goes to row 10, output adjustments. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NA', 'NA-S-15-CAP', 'Sale of a capital good, standard rate 15 %', '{}'::jsonb, 'The sale of an asset of the business, charged at the general rate', 'percent', 15, 'sale', 'domestic', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 6(1) — tax is levied at the rate of 15 per cent on the value of every taxable supply by a registered person and of every import of goods or services other than an exempt import; s. 6(2) — the supplier accounts for it on a supply, the importer pays it on goods, the recipient pays it on imported services. Declared on row 9 of the VAT 2 return, "Capital goods sold", in the 15 % column; a credit note goes to row 10. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', 'S', null, 15, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat2-return', null, null, null, null),
  ('NA', 'NA-S-EX', 'Sale, exempt', '{}'::jsonb, 'Financial services, residential accommodation let under a lease, education, public transport and medical services', 'percent', 0, 'sale', 'exempt', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 10 and Schedule IV, paragraph 2 — among the exempt supplies: financial services, accommodation in a dwelling under a lease, leasehold land, education services, public transport services, a supply of goods or services as a fringe benefit to an employee, and medical or paramedical services by the practitioners the Schedule names; s. 10(2) — a supply the Act zero-rates is never exempt. An exempt supply gives no right to deduct the input tax of what it costs (s. 19(3)). Declared on row 8 of the VAT 2 return in the exempt column. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', 'E', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NA', 'NA-S-Z', 'Sale, zero-rated (local)', '{}'::jsonb, 'A supply charged at zero per cent without leaving Namibia: maize meal and mahango, fuel, residential utilities, bread and other listed basic foods, and the other items of Schedule III', 'percent', 0, 'sale', 'domestic', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 9 and Schedule III, paragraph 2 — among the supplies charged at zero per cent: (r) petrol and distillate fuels subject to the fuel levy; (s) mahango, mahango meal and maize meal; (w) electricity, water, refuse removal and sewerage to a residential account; (z) telecommunication services to a residential account; (aa) livestock other than game; (ee) fresh and dried beans, sunflower cooking oil, bread and cake flour and bread; (ff) dry white and brown granular sugar and fresh milk; (ii) funeral undertaking services; (jj) sanitary pads, none of them when furnished as a meal or as cooked or prepared food. The list is long and is amended by Finance Acts: the pack carries the code, and the accountant checks the item against the current Schedule III. Declared on row 8 of the VAT 2 return in the zero-rated column. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', 'Z', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NA', 'NA-S-Z-EXP', 'Sale, zero-rated (export)', '{}'::jsonb, 'Goods exported by the supplier, and services to a non-resident outside Namibia', 'percent', 0, 'sale', 'export', date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 9 and Schedule III, paragraph 2 — (a) goods the supplier has entered for export under the Customs and Excise Act and exported; (b) goods the Commissioner is satisfied have been exported by the supplier; (h) international transport services; (o) services to a non-resident person who is outside Namibia when they are supplied, with the exceptions the paragraph lists; s. 9(2) — the supplier obtains and keeps the documentary proof the Commissioner accepts. Declared on row 8 of the VAT 2 return in the zero-rated column, the only zero column the form has. The start date is the earliest day the pack claims, not the history of the rule: this pack is written for books from 2024, and the 15 % of s. 6(1) is the rate of the consolidated text it read.', 'G', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
