insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('NA', 'NA-VAT2', 'VAT 2 — Return for Value Added Tax', array['month', 'bimonth']::declaration_period[], null, date '2024-01-01', null, 'Value-Added Tax Act, 2000, s. 23(2) — the tax period of a registered person is two calendar months: Category A, ending in January, March, May, July, September and November; Category B, ending in February, April, June, August, October and December, the Commissioner choosing the category (s. 23(3)); a farmer may elect two, four, six or twelve months, and a person registered under s. 15(4) six months. s. 24(1) — a return is furnished for every period whether or not tax is payable. `bimonth` is anchored on January–February, which is Category B; a Category A taxpayer (December–January, February–March…) is not expressible by this format and is recorded in the README. The category is NamRA''s decision about the taxpayer, so no period_default is declared and `ekwo init` asks.', true,'day_of_month_after_period'::filing_deadline_rule, 25, null, 'Value-Added Tax Act, 2000, s. 24(1) — not later than the twenty-fifth day of the month following the end of the tax period; the NamRA brochures say the same. The Commissioner may extend the time to furnish a return but not the time to pay (s. 24(4) and (5)).', 'vat-act', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
