update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Value-Added Tax Act, 2000, s. 21 and Schedule VI, paragraph 1(d) — a tax invoice carries an individualised serial number and its date of issue. The Act asks for a serial number, not for a series without gaps restarting each year, so `numbering` is `sequential`.',
  numbering_source_key          = 'vat-act',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Value-Added Tax Act, 2000, s. 7(1) — a supply takes place when an invoice is issued or a payment is received, whichever is earlier. Delivery is not a time of supply in the general rule, but Ekwo''s closed vocabulary offers `earliest_of_delivery_or_payment` as the nearest value; the sections 7(2) to 7(8) special cases (connected persons, goods under a credit agreement, continuous supplies and others) are not modelled and a gap is recorded in the README.',
  tax_point_source_key          = 'vat-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Namibian statute or notice the pack could open obliges a business to exchange a structured electronic invoice: there is no Peppol authority, no published profile and no scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`. What the Value-Added Tax Act, 2000 requires is a tax invoice carrying the particulars of Schedule VI, paragraph 1, on paper or in any form. Trade and tax press report that the Ministry of Finance planned an e-invoicing system connected to NamRA''s ITAS, first dated April 2026, then moved to a phased rollout over the 2026/27 to 2028/29 budget period without a fixed date; the pack found no NamRA or Ministry document that sets a date, a profile or a platform, so it records none and the gap is written in the README.',
  einvoice_source_key           = 'vat-act',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'NA';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('NA', 'export', 'export', 'Zero-rated supply under section 9 and paragraph 2 of Schedule III to the Value-Added Tax Act, 2000.', '{}'::jsonb, 20, date '1970-01-01', null, 'Value-Added Tax Act, 2000, s. 9(1) and Schedule III, paragraph 2(a) and (b) — a supply of goods the supplier has entered for export and exported, or that the Commissioner is satisfied has been exported, is charged at zero per cent; s. 9(2) — the registered person obtains and keeps the documentary proof the Commissioner accepts. Namibia is outside the European Union''s common system and carries no VATEX code, so the sentence names the section the zero rate is claimed under.'),
  ('NA', 'exempt', 'exempt', 'Exempt supply under section 10 and paragraph 2 of Schedule IV to the Value-Added Tax Act, 2000: no VAT is charged.', '{}'::jsonb, 30, date '1970-01-01', null, 'Value-Added Tax Act, 2000, s. 10(1) and Schedule IV, paragraph 2 — the supplies exempt from the tax of s. 6(1)(a), among them financial services, accommodation in a dwelling let under a lease, leasehold land let, education, public transport and medical or paramedical services.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;

update country_defaults set
  tax_payee_name       = 'Namibia Revenue Agency',
  tax_payee_source_key = 'itas-portal'
 where country = 'NA';
